use std::{process::{Command,Stdio},io::{Read,Write},time::Duration};
#[test]fn open_pipe_delivers_one_idle_job_followup_without_more_input(){let d=tempfile::tempdir().unwrap();let project=d.path().join("proj");std::fs::create_dir(&project).unwrap();let cfg=d.path().join("rig.toml");std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"bash\",\"args\":{\"description\":\"Idle probe\",\"command\":\"sleep .2; printf idle-pipe-finished\",\"run_in_background\":true}}\n{\"tool\":\"job_list\",\"args\":{}}\n").unwrap();let mut child=Command::new(env!("CARGO_BIN_EXE_hs-repl")).args(["--config",cfg.to_str().unwrap(),"--dir",d.path().join("run").to_str().unwrap(),"--project-dir",project.to_str().unwrap(),"--max-steps","1"]).env("HS_SEQMODEL_SCRIPT",script).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();let mut input=child.stdin.take().unwrap();writeln!(input,"Start idle probe").unwrap();std::thread::sleep(Duration::from_secs(2));writeln!(input,"/quit").unwrap();drop(input);let mut text=String::new();child.stdout.take().unwrap().read_to_string(&mut text).unwrap();child.wait().unwrap();let count=text.lines().filter_map(|l|serde_json::from_str::<serde_json::Value>(l).ok()).filter(|v|v["outcome"].is_string()).count();assert_eq!(count,2,"{text}");}
#[test]fn eof_and_quit_exit_without_waiting_for_pending_job(){for end in ["","/quit\n"]{let d=tempfile::tempdir().unwrap();let project=d.path().join("proj");std::fs::create_dir(&project).unwrap();let cfg=d.path().join("rig.toml");std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"bash\",\"args\":{\"description\":\"Pending at exit\",\"command\":\"sleep 10\",\"run_in_background\":true}}\n").unwrap();let mut child=Command::new(env!("CARGO_BIN_EXE_hs-repl")).args(["--config",cfg.to_str().unwrap(),"--dir",d.path().join("run").to_str().unwrap(),"--project-dir",project.to_str().unwrap(),"--max-steps","1"]).env("HS_SEQMODEL_SCRIPT",script).stdin(Stdio::piped()).stdout(Stdio::null()).stderr(Stdio::null()).spawn().unwrap();let mut input=child.stdin.take().unwrap();write!(input,"Start pending job\n{end}").unwrap();drop(input);let start=std::time::Instant::now();loop{if child.try_wait().unwrap().is_some(){break}if start.elapsed()>Duration::from_secs(3){child.kill().unwrap();child.wait().unwrap();panic!("EOF/quit blocked on job")}std::thread::sleep(Duration::from_millis(20));}}}
